\textbf{\label{TR}}Suppose $a\leq 1$, $b>0$\ and $c\geq \max \left\{
-a,b\right\} $. If $c\geq \max \left\{ 1-2a,2b\right\} $, then 
\begin{equation}
\left[ F\left( -a,b;c;x\right) \right] ^{1/a}\geq M_{p}\left( 1-x;\frac{b}{c} 
\right)  \label{Hm>Pm-p}
\end{equation} 
\ for all $x\in \left( 0,1\right) $ if and only if $p\leq p_{0}$, where 
\begin{equation}
p_{0}=\frac{a+c}{1+c}.  \label{p0}
\end{equation} 
If $c\leq \min \left\{ 1-2a,2b\right\} $, then 
\begin{equation}
\left[ F\left( -a,b;c;x\right) \right] ^{1/a}\leq M_{p}\left( 1-x;\frac{b}{c} 
\right)  \label{Hm<Pm-p}
\end{equation} 
for all $x\in \left( 0,1\right) ,$if and only if $p\geq p_{0}$. If $ 
c=1-2a=2b $; or $c=\max \left\{ -a,b\right\} $; or $a=1$, then the equality
holds.

\label{R-p0*<1}To ensure $p_{0}^{\ast }$ exists, it is clearly required that
$c>\max \left\{ -a,b,b-a\right\} >0$. Thus, 
\begin{equation}
p_{0}^{\ast }=\frac{a\ln \left( 1-b/c\right) }{\ln \frac{\Gamma \left(
c\right) \Gamma \left( c+a-b\right) }{\Gamma \left( c+a\right) \Gamma \left(
c-b\right) }}\text{ if }a\neq 0\text{ and }p_{0}^{\ast }=\frac{\ln \left(
1-b/c\right) }{\psi \left( c-b\right) -\psi \left( c\right) }.  \label{p0*}
\end{equation} 
Carlson \cite[Eq. (2.7)]{Carlson-PAMS-16-1966} pointed out that $a\mapsto  
\left[ F\left( -a,b;c;x\right) \right] ^{1/a}$ is increasing on $\mathbb{R}$ 
, then so is
\begin{equation*}
a\mapsto \frac{1}{a}\ln F\left( -a,b;c;1\right) =\frac{1}{a}\ln \frac{\Gamma
\left( c\right) \Gamma \left( c+a-b\right) }{\Gamma \left( c+a\right) \Gamma
\left( c-b\right) }.
\end{equation*} 
This implies the following two conclusions:

(i) $p_{0}^{\ast }$ is an increasing function of $a$ on $\mathbb{R}$, and
therefore, $0<p_{0}^{\ast }<\left( >\right) 1$ if $a<\left( >1\right) $.

(ii) If $a<1$, then 
\begin{equation}
\frac{1}{a}\ln \frac{\Gamma \left( c\right) \Gamma \left( c+a-b\right) }{ 
\Gamma \left( c+a\right) \Gamma \left( c-b\right) }<\ln \left( 1-\frac{b}{c} 
\right) <0.  \label{1/alng<0}
\end{equation}

\label{MT-3}Suppose that (i) $a<1$, $b>0$ and $c>\max \left\{ b,b-a\right\} $ 
; (ii) $p_{0}$ and $p_{0}^{\ast }$ be respectively defined by (\ref{p0}) and
(\ref{p0*}) with $p_{0}^{\ast }>p_{0}$. If $\left( a,b,c\right) \in \left(
E_{1,1,\pm 1}\cup E_{1,\pm 1,-1}\right) \backslash E_{0,0,-1}$, where 
\begin{eqnarray*}
E_{1,1,\pm 1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast
}\right) \geq 0\text{, }\Delta \gamma _{1}\left( p_{0}^{\ast }\right) \geq
0\right\} , \\
E_{1,\pm 1,-1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast
}\right) >0\text{, }\gamma _{1}\left( p_{0}^{\ast }\right) \leq 0\right\} ,
\\
E_{0,0,-1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast
}\right) =\Delta \gamma _{1}\left( p_{0}^{\ast }\right) =0,\gamma _{1}\left(
p_{0}^{\ast }\right) \leq 0\right\} ,
\end{eqnarray*} 
then the second Hm-Pm inequality 
\begin{equation}
\left[ F\left( -a,b;c;x\right) \right] ^{1/a}<M_{p_{0}^{\ast }}\left( 1-x; 
\frac{b}{c}\right)   \label{Hm<Pm-p0*}
\end{equation} 
holds for $x\in \left( 0,1\right) $.

\label{MT-4}Suppose that (i) $a<1$, $b>0$ and $c>\max \left\{ b,b-a\right\} $ 
; (ii) $p_{0}$ and $p_{0}^{\ast }$ be respectively defined by (\ref{p0}) and
(\ref{p0*}) with $p_{0}^{\ast }<p_{0}$. If $\left( a,b,c\right) \in \left(
E_{-1,-1,\pm 1}\cup E_{-1,\pm 1,1}\right) \backslash E_{0,0,1}$, where 
\begin{eqnarray*}
E_{-1,-1,\pm 1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast
}\right) \leq 0\text{, }\Delta \gamma _{1}\left( p_{0}^{\ast }\right) \leq
0\right\} , \\
E_{-1,\pm 1,1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast
}\right) <0\text{, }\gamma _{1}\left( p_{0}^{\ast }\right) \geq 0\right\} ,
\\
E_{0,0,1} &=&\left\{ \left( a,b,c\right) :\delta \left( p_{0}^{\ast }\right)
=\Delta \gamma _{1}\left( p_{0}^{\ast }\right) =0,\gamma _{1}\left(
p_{0}^{\ast }\right) \geq 0\right\} ,
\end{eqnarray*} 
then the second Hm-Pm inequality 
\begin{equation}
\left[ F\left( -a,b;c;x\right) \right] ^{1/a}>M_{p_{0}^{\ast }}\left( 1-x; 
\frac{b}{c}\right)  \label{Hm>Pm-p0*}
\end{equation} 
holds for $x\in \left( 0,1\right) $.

\label{C1}Suppose $a\in (-1,1)$. If $a>\left( <\right) -1/2$, then the
inequality 
\begin{equation}
M_{p_{0}}\left( 1-x,\frac{1}{2}\right) <\left( >\right) \left[ F\left(
-a,1;2;x\right) \right] ^{1/a}<\left( >\right) M_{p_{0}^{\ast }}\left( 1-x, 
\frac{1}{2}\right)   \label{F-a,1,2<>}
\end{equation} 
holds for $x\in (0,1)$ with the best constants $p_{0}=\left( a+2\right) /3$
and $p_{0}^{\ast }=\left( a\ln 2\right) /\ln \left( 1+a\right) $.

\label{C2}Suppose $a\in (0,1/2]$. Then the inequality 
\begin{equation}
M_{p_{0}}\left( 1-x,a\right) <\left[ F\left( -a,a;1;x\right) \right]
^{1/a}<M_{p_{0}^{\ast }}\left( 1-x,a\right)   \label{F-a,a,1<>}
\end{equation} 
holds for $x\in (0,1)$ with the best constants 
\begin{equation*}
p_{0}=\frac{a+1}{2}\text{ \ and \ }p_{0}^{\ast }=-\frac{a\ln \left(
1-a\right) }{\ln \frac{\pi a}{\sin \left( \pi a\right) }}.
\end{equation*}

(i) Since $c-2b=1-2a\geq 0$ and 
\begin{equation*}
\delta \left( p_{0}\right) =a-a+1-\frac{a+1}{2}=\frac{1-2a}{2}\geq 0,
\end{equation*} 
by Remark \ref{R-p0*><p0}, $p_{0}^{\ast }>p_{0}$, which proves the first
assertion (i).

(ii) We have $\delta \left( p_{0}^{\ast }\right) =1-p_{0}^{\ast }>0$, which
follows from Remark \ref{R-p0*<1} (i).

(iii) We have 
\begin{equation*}
\Delta \gamma _{1}\left( p_{0}^{\ast }\right) =-4p_{0}^{\ast 2}+2\left(
a^{2}+2\right) p_{0}^{\ast }-a\left( a+1\right) =-4\left( p_{0}^{\ast
}-p_{1}\right) \left( p_{0}^{\ast }-p_{2}\right) ,
\end{equation*} 
where 
\begin{eqnarray*}
p_{1} &=&p_{1}\left( a\right) =\frac{a^{2}+2-\sqrt{a^{4}-4a+4}}{4}, \\
p_{2} &=&p_{2}\left( a\right) =\frac{a^{2}+2+\sqrt{a^{4}-4a+4}}{4}.
\end{eqnarray*} 
If we show that $p_{0}^{\ast }>p_{1}$ and $p_{0}^{\ast }<p_{2}$, then $ 
\Delta \gamma _{1}\left( p_{0}^{\ast }\right) >0$, and the proof is
completed. Now, since 
\begin{equation*}
p_{1}^{\prime }\left( a\right) =\frac{1}{2}\frac{a\sqrt{a^{4}-4a+4}+1-a^{3}}{ 
\sqrt{a^{4}-4a+4}}>0,
\end{equation*} 
we have $p_{1}\left( a\right) <p_{1}\left( 1/2\right) =\left( 9-\sqrt{33} 
\right) /16$. Applying (i) of this lemma yields 
\begin{equation*}
p_{0}^{\ast }>p_{0}=\frac{a+1}{2}>\frac{1}{2}.
\end{equation*} 
Thus, 
\begin{equation*}
p_{0}^{\ast }-p_{1}>\frac{1}{2}-\frac{9-\sqrt{33}}{16}=\frac{\sqrt{33}-1}{16} 
>0.
\end{equation*} 
Using the known inequality $\left( \sin x\right) /x<e^{-x^{2}/6}\,$for $x\in
\left( 0,\pi /2\right) $ \cite[p. 606]{Yang-JMI-7-2013} which implies 
\begin{equation*}
\ln \frac{\pi a}{\sin \left( \pi a\right) }>\frac{\left( \pi a\right) ^{2}}{6 
}\text{ \ for }a\in (0,1/2],
\end{equation*}
we have 
\begin{equation*}
p_{0}^{\ast }=-\frac{a\ln \left( 1-a\right) }{\ln \left( \pi a/\sin \left(
\pi a\right) \right) }<-\frac{a\ln \left( 1-a\right) }{\left( \pi a\right)
^{2}/6}=-\frac{6}{\pi ^{2}}\frac{\ln \left( 1-a\right) }{a}=:p_{3}\left(
a\right) ,
\end{equation*} 
which is increasing in $a$ on $\left( 0,1\right) $ since 
\begin{equation*}
p_{3}^{\prime }\left( a\right) =\frac{6}{\pi ^{2}}\frac{a+\left( 1-a\right)
\ln \left( 1-a\right) }{a^{2}\left( 1-a\right) }>0\text{ for }a\in \left(
0,1\right) .
\end{equation*} 
On the other hand, since 
\begin{eqnarray*}
p_{2}^{\prime }\left( a\right)  &=&\frac{1}{2}\frac{a\sqrt{a^{4}-4a+4} 
-\left( 1-a^{3}\right) }{\sqrt{a^{4}-4a+4}}, \\
\left( a\sqrt{a^{4}-4a+4}\right) ^{2}-\left( 1-a^{3}\right) ^{2}
&=&-2a^{3}+4a^{2}-1<0\text{ for }a\in (0,1/2],
\end{eqnarray*} 
we have $p_{2}^{\prime }\left( a\right) <0$ for $a\in (0,1/2]$. Thus, $ 
p_{3}\left( a\right) -p_{2}\left( a\right) $ is increasing in $a$ on $(0,1/2]
$, and hence, 
\begin{equation*}
p_{3}\left( a\right) -p_{2}\left( a\right) <p_{3}\left( \frac{1}{2}\right)
-p_{2}\left( \frac{1}{2}\right) =\frac{12}{\pi ^{2}}\ln 2-\frac{9+\sqrt{33}}{ 
16}=-0.078...<0
\end{equation*} 
for $a\in (0,1/2]$. It then follows that
\begin{equation*}
p_{0}^{\ast }-p_{2}<p_{3}\left( a\right) -p_{2}\left( a\right) <0\text{ for } 
a\in (0,1/2].
\end{equation*} 
This completes the proof.

The complete $p$-elliptic integrals of the second is defined by 
\begin{equation*}
E_{p}\left( r\right) =\int_{0}^{1}\left( \frac{1-r^{p}t^{p}}{1-t^{p}}\right)
^{1/p}dt=\frac{\pi _{p}}{2}F\left( -\frac{1}{p},\frac{1}{p};1;r^{p}\right) ,
\end{equation*} 
where $\pi _{p}=B\left( 1/p,1-1/p\right) /p$ (see \cite{Takeuchi-KMJ-39-2016} 
). Let $a=1/p$ and $r^{\prime }=\left( 1-r^{p}\right) ^{1/p}$. The double
inequality (\ref{F-a,a,1<>}) can be written as 
\begin{equation}
\frac{\pi _{p}}{2}M_{\tau _{0}}\left( r^{\prime },\frac{1}{p}\right) <\frac{ 
\pi _{p}}{2}F\left( -\frac{1}{p},\frac{1}{p};1;r^{p}\right) <\frac{\pi _{p}}{ 
2}M_{\tau _{0}^{\ast }}\left( r^{\prime },\frac{1}{p}\right)   \label{p-e2<>}
\end{equation} 
holds for $p\geq 2$ and $r^{\prime }\in \left( 0,1\right) $ with the best
constants 
\begin{equation*}
\tau _{0}=\frac{p+1}{2}\text{ \ and \ }\tau _{0}^{\ast }=\frac{\ln \left(
p/\left( p-1\right) \right) }{\ln \left( \pi _{p}/2\right) }.
\end{equation*} 
The double inequality (\ref{p-e2<>}) was established in \cite[Corollary 1.3] 
{Zhao-BMSS-46-2023}.

Taking $a=1/2$ in Corollary \ref{C2} gives 
\begin{equation*}
M_{p_{0}}\left( 1-x,\frac{1}{2}\right) <\left[ F\left( -\frac{1}{2},\frac{1}{ 
2};1;x\right) \right] ^{2}<M_{p_{0}^{\ast }}\left( 1-x,\frac{1}{2}\right)
\end{equation*} 
for $x\in \left( 0,1\right) $ with the best constants $p_{0}=3/4$ and $ 
p_{0}^{\ast }=\left( \ln 2\right) /\left( 2\ln \left( \pi /2\right) \right)
=0.767$. The above double inequality is equivalent to 
\begin{equation*}
M_{2p_{0}}\left( r^{\prime },\frac{1}{2}\right) <\frac{2}{\pi }E\left(
r\right) <M_{2p_{0}^{\ast }}\left( r^{\prime },\frac{1}{2}\right) \text{ \ } 
r^{\prime }=\sqrt{1-r^{2}},
\end{equation*} 
\ where the first one was proved by Qiu and Shen \cite[Theorem 2] 
{Qiu-JHIEE-3-1997} in 1997, while the second one was due to Qiu \cite[ 
Corollary (1)]{Qiu-JHIEE-20(1)-2000} in 2000 (see also \cite 
{Alzer-JCAM-172-2004}). A skillful proof of the first one was presented by
Barnard, Pearce and Richards \cite[Theorem 1.1]{Barnard-JMA-31-2000} (see
also \cite{Barnard-JMA-32-2000}, \cite{Barnard-JMAA-260-2001}).

The inequality 
\begin{equation*}
\left[ F\left( \frac{3}{2},\frac{1}{2};3;x\right) \right] ^{-2/3}<M_{p_{0}^{ 
\ast }}\left( 1-x,\frac{1}{6}\right)
\end{equation*} 
holds for $x\in \left( 0,1\right) $ with the best constants $p_{0}^{\ast
}=0.516...$.

The inequality 
\begin{equation*}
\left[ F\left( \frac{1}{2},\frac{9}{4};3;x\right) \right] ^{-2}>M_{p_{0}^{ 
\ast }}\left( 1-x,\frac{3}{4}\right)
\end{equation*} 
holds for $x\in \left( 0,1\right) $ with the best constants $p_{0}^{\ast
}=0.464...$.

\label{R-C3,4}In the above two corollaries, $\min \left\{ 2b,1-2a\right\}
<c<\max \left\{ 2b,1-2a\right\} $. Even if Conjecture \ref{Cj-BRT} is proved
to be valid, it still does not work.

\label{P-PH-rr}Let $\left( a-1\right) \left( c-a\right) \neq 0$ and $ 
-c\notin \mathbb{N\cup }\left\{ 0\right\} $. Then for $p\in \mathbb{R}$, we
have 
\begin{equation}
U\left( x\right) =\left( 1-x\right) ^{p}F\left( a,b;c;x\right)
=\sum_{n=0}^{\infty }u_{n}x^{n},  \label{U}
\end{equation} 
with $u_{0}=1$, $u_{1}=ab/c-p$ and for $n\geq 1$, 
\begin{eqnarray*}
u_{n+1} &=&\frac{2n^{2}+\left( a+b+c-2p-1\right) n+ab-cp}{\left( n+1\right)
\left( n+c\right) }u_{n} \\
&&-\frac{\left( n+a-p-1\right) \left( n+b-p-1\right) }{\left( n+1\right)
\left( n+c\right) }u_{n-1}.
\end{eqnarray*}

An application of Proposition \ref{P-PH-rr} shows that the sequence $\left\{
u_{n}\right\} _{n\geq 1}$ satisfies 
\begin{equation}
u_{n+1}=\alpha _{n}u_{n}-\beta _{n}u_{n-1}\text{ for }n\geq 1  \label{un-rr}
\end{equation} 
with $u_{0}=1$ and $u_{1}=\left( 1-a\right) b/\left( c+1\right) -p+1$, where 
\begin{eqnarray}
\alpha _{n} &=&\frac{2n^{2}+\left( c-a+b-2p+3\right) n+\left( 1-a\right)
b+\left( c+1\right) \left( 1-p\right) }{\left( n+1\right) \left(
n+c+1\right) },  \label{alphn} \\
\beta _{n} &=&\frac{\left( n+1-a-p\right) \left( n+b-p\right) }{\left(
n+1\right) \left( n+c+1\right) }.  \label{betan}
\end{eqnarray} 
It is clear that $\alpha _{n},\beta _{n}>0$ for $n\geq 1$ if $a<1,c>b>0$, $ 
p\in \left( 0,1\right) $.

\label{L-xin-rr}Let $u_{n}$ and $v_{n}$ be defined by (\ref{un}) and (\ref 
{vn}), respectively. The sequence $\xi _{n}\equiv \xi _{n}\left( p\right)
=u_{n}-v_{n}$ satisfies the recurrence relation 
\begin{equation}
\xi _{n+1}-\alpha _{n}\xi _{n}+\beta _{n}\xi _{n-1}=\tau _{n}\gamma
_{n}v_{n-1}  \label{xin-rr-0}
\end{equation} 
where $\alpha _{n}$ and $\beta _{n}$ are given by (\ref{alphn}) and (\ref 
{betan}), respectively. Moreover, if $a<1,c>b>0$, $p\in \left( 0,1\right) $
then $\alpha _{n},\beta _{n}>0$ for $n\geq 1$.

\label{L-xin-rr-a1}Let $u_{n}$ and $v_{n}$ be defined by (\ref{un}) and (\ref 
{vn}), respectively. The sequence $\xi _{n}\equiv \xi _{n}\left( p\right)
=u_{n}-v_{n}$ satisfies the recurrence relation 
\begin{equation}
\left( \xi _{n+1}-\theta _{n}\xi _{n}\right) -\lambda _{n}\left( \xi
_{n}-\theta _{n-1}\xi _{n-1}\right) =\tau _{n}\gamma _{n}u_{n-1},
\label{xin-rr-2}
\end{equation} 
where 
\begin{eqnarray}
\theta _{n} &=&\frac{v_{n+1}}{v_{n}}=\frac{\left( n+1-a\right) \left(
n+b+1\right) }{\left( n+1\right) \left( n+c+1\right) },  \label{thn} \\
\lambda _{n} &=&\lambda _{n}\left( p\right) =\alpha _{n}-\theta _{n}=\frac{ 
n^{2}+\left( c-2p+1\right) n+\left( a+c-p-cp\right) }{\left( n+1\right)
\left( n+c+1\right) },  \label{ln}
\end{eqnarray} 
$\gamma _{n}=\gamma _{n}\left( p\right) $ and $\tau _{n}$ are given by (\ref 
{gamn}) and (\ref{tn}), respectively. Moreover, if $a<1$, $b>0$, $c>\max
\left\{ -a,b\right\} $, then $\theta _{n}>0$ for $n\geq 1$, $\lambda
_{n}\left( p\right) >0$ for $n\geq 2$.

\label{L-l1p0*>0}Let $a<1$, $b>0$, $c>\max \left\{ b,b-a\right\} $. Then 
\begin{equation*}
\lambda _{1}\left( p_{0}^{\ast }\right) =\frac{a+2c+2-\left( 3+c\right)
p_{0}^{\ast }}{2\left( c+2\right) }>0.
\end{equation*}

By (\ref{1/alng<0}), to prove $\lambda _{1}\left( p_{0}^{\ast }\right) >0$,
it suffices to 
\begin{equation*}
\mu \left( b\right) =\frac{1}{a}\ln \frac{\Gamma \left( c\right) \Gamma
\left( c+a-b\right) }{\Gamma \left( c+a\right) \Gamma \left( c-b\right) }- 
\frac{3+c}{a+2c+2}\ln \left( 1-b/c\right) <0,
\end{equation*} 
which, due to $\mu \left( 0\right) =0$, in turn suffices to prove that $ 
b\mapsto \mu \left( b\right) $ is decreasing on $\left( 0,\min \left\{
c,c+a\right\} \right) $. Differentiation yields 
\begin{equation*}
\left( c-b\right) \mu ^{\prime }\left( b\right) =-\left( c-b\right) \frac{ 
\psi \left( a+c-b\right) -\psi \left( c-b\right) }{a}+\frac{3+c}{a+2c+2} 
=:\mu _{1}\left( b\right) .
\end{equation*} 
It was proved in \cite[Corollary 1]{Tian-RACSAM-115-2021} (see also \cite 
{Yang-JMAA-455-2017}) that, for $0\leq p-q\neq 1$, the function $t\mapsto
\left( t+r\right) \left[ \psi \left( t+p\right) -\psi \left( t+q\right)  
\right] /\left( p-q\right) $ is increasing (decreasing) on $\left( -q,\infty
\right) $ if and only if $r\leq \min \left\{ q,\left( p+q-1\right)
/2\right\} $ ($r\geq \max \left\{ q,\left( p+q-1\right) /2\right\} $). Then
the function 
\begin{equation*}
t\mapsto t\frac{\psi \left( t+a\right) -\psi \left( t\right) }{a}
\end{equation*} 
is decreasing on $\left( -\min \left\{ 0,a\right\} ,\infty \right) $ if $a<1$ 
. This implies that $b\mapsto \mu _{1}\left( b\right) $ is also decreasing
on $\left( 0,\min \left\{ c,c+a\right\} \right) $, which yields 
\begin{equation*}
\frac{1}{c}\mu _{1}\left( b\right) <\frac{1}{c}\mu _{1}\left( 0\right) =- 
\frac{\psi \left( a+c\right) -\psi \left( c\right) }{a}+\frac{3+c}{c\left(
a+2c+2\right) }=\mu _{2}\left( c\right) .
\end{equation*}

If we prove $\mu _{2}\left( c\right) <0$, then $\mu _{1}\left( b\right) <0$,
and then $\mu ^{\prime }\left( b\right) <0$, and the proof is completed.
Now, since 
\begin{eqnarray*}
\mu _{2}\left( c+1\right) -\mu _{2}\left( c\right) &=&\frac{\psi \left(
c+1\right) -\psi \left( c+1+a\right) }{a}+\frac{4+c}{\left( c+1\right)
\left( a+2c+4\right) } \\
&&-\left[ \frac{\psi \left( c\right) -\psi \left( c+a\right) }{a}+\frac{3+c}{ 
c\left( a+2c+2\right) }\right]
\end{eqnarray*} 
\begin{equation*}
=\frac{2\left( c^{2}+1-a\right) \left( a+c\right) +2c^{2}+\left(
a^{2}+1\right) c+\left( 1-a\right) \left( 5c+8\right) }{c\left( c+1\right)
\left( a+c\right) \left( a+2c+2\right) \left( a+2c+4\right) }>0,
\end{equation*} 
we have 
\begin{equation*}
\mu _{2}\left( c\right) <\mu _{2}\left( c+1\right) <\cdot \cdot \cdot
<\lim_{n\rightarrow \infty }\mu _{2}\left( c+n\right) =0,
\end{equation*} 
which completes the proof.

Due to $b>0$ and $c>\max \left\{ b,b-a\right\} $, so $c,c+a,c-b,c+a-b>0$,
which guarantees the existence of $p_{0}^{\ast }$. It is easy to see that,
for $p=p_{0}^{\ast }$, 
\begin{equation*}
f_{p_{0}^{\ast }}\left( 1\right) =\left( \dfrac{c}{c-b}\right)
^{1/p_{0}^{\ast }}\left[ \dfrac{\Gamma \left( c\right) \Gamma \left(
c+a-b\right) }{\Gamma \left( c+a\right) \Gamma \left( c-b\right) }\right]
